from brian.motors import EV3LargeMotor
from brian.motors import MotorPort
from brian.sensors.EV3 import GyroSensorEV3
from brian.sensors import SensorPort
from brian.motors import EV3MediumMotor
from brian.sensors.EV3 import UltrasonicSensorEV3
from brian.sensors.EV3 import TouchSensorEV3
import time

HowFar_ = None
gyro = None
pas = None
left = None
Start_stop = None
right = None
rychlost = None
TouchZavora = None
HowFarUntilFrontRow = None
HowFarUntilBackRow = None
US = None

def sensor_retry(sensor, call_fun):
  from brian.sensors import SensorIsNotReadyError
  while True:
    try:
      sensor.wait_until_ready()
      return call_fun()
    except SensorIsNotReadyError:
      # Čtení senzoru může selhat. Opakuj při chybě
      pass

# Popište tuto funkci...
def Beninging_config():
  global HowFar_, gyro, pas, left, Start_stop, right, rychlost, TouchZavora, HowFarUntilFrontRow, HowFarUntilBackRow, US
  left = EV3LargeMotor(MotorPort.D)
  right = EV3LargeMotor(MotorPort.C)
  gyro = GyroSensorEV3(SensorPort.S1)
  pas = EV3MediumMotor(MotorPort.A)
  sensor_retry(gyro, gyro.set_zero_point)
  US = UltrasonicSensorEV3(SensorPort.S2)
  TouchZavora = TouchSensorEV3(SensorPort.S3)
  Start_stop = TouchSensorEV3(SensorPort.S4)
  HowFarUntilFrontRow = 50
  HowFarUntilBackRow = 0
  time.sleep(0.1)

def motor_retry(motor, call_fun):
  from brian.motors import MotorIsNotReadyError
  while True:
    try:
      motor.wait_until_ready()
      return call_fun()
    except MotorIsNotReadyError:
      # Ovládání motoru může selhat. Opakuj při chybě
      pass

# Popište tuto funkci...
def START__Gate_reset_():
  global HowFar_, gyro, pas, left, Start_stop, right, rychlost, TouchZavora, HowFarUntilFrontRow, HowFarUntilBackRow, US
  Start_stop.wait_for_press()
  time.sleep(0.1)
  while sensor_retry(Start_stop, Start_stop.is_pressed):
    motor_retry(pas, lambda: pas.run_at_speed(360))
  Start_stop.wait_for_release()

# Skopčenej kod z minulého roku, je to nastavené
# na současné proporce, snad by to mělo fungovat
def Drive_Forward_Until_Block_Detected():
  global HowFar_, gyro, pas, left, Start_stop, right, rychlost, TouchZavora, HowFarUntilFrontRow, HowFarUntilBackRow, US
  sensor_retry(gyro, gyro.set_zero_point)
  time.sleep(0.1)
  motor_retry(left, lambda: left.reset_angle(0))
  motor_retry(right, lambda: right.reset_angle(0))
  while not sensor_retry(US, US.distance_mm) <= 170:
    print(sensor_retry(gyro, gyro.angle))
    motor_retry(left, lambda: left.run_at_speed(360 - 8 * sensor_retry(gyro, gyro.angle)))
    motor_retry(right, lambda: right.run_at_speed(360 + 8 * sensor_retry(gyro, gyro.angle)))
  motor_retry(left, left.brake)
  motor_retry(right, right.brake)

# Skopčenej kod z minulého roku, je to nastavené
# na současné proporce, snad by to mělo fungovat
def DriveBackward(HowFar_):
  global gyro, pas, left, Start_stop, right, rychlost, TouchZavora, HowFarUntilFrontRow, HowFarUntilBackRow, US
  motor_retry(left, lambda: left.reset_angle(0))
  while motor_retry(left, left.current_angle) >= HowFar_:
    print(sensor_retry(gyro, gyro.angle))
    motor_retry(left, lambda: left.run_at_speed(-360 - 8 * sensor_retry(gyro, gyro.angle)))
    motor_retry(right, lambda: right.run_at_speed(-360 + 8 * sensor_retry(gyro, gyro.angle)))
  motor_retry(left, left.brake)
  motor_retry(right, right.brake)

# Popište tuto funkci...
def Collect_Bloct_To_Front_Row():
  global HowFar_, gyro, pas, left, Start_stop, right, rychlost, TouchZavora, HowFarUntilFrontRow, HowFarUntilBackRow, US
  Drive_Forward_Until_Block_Detected()
  while motor_retry(left, left.current_angle) <= HowFarUntilFrontRow or motor_retry(right, right.current_angle) <= HowFarUntilFrontRow:
    print(sensor_retry(gyro, gyro.angle))
    motor_retry(left, lambda: left.run_at_speed(180 - 8 * sensor_retry(gyro, gyro.angle)))
    motor_retry(right, lambda: right.run_at_speed(180 + 8 * sensor_retry(gyro, gyro.angle)))
  motor_retry(left, left.brake)
  motor_retry(right, right.brake)

# Popište tuto funkci...
def Collect_Bloct_To_Back_Row():
  global HowFar_, gyro, pas, left, Start_stop, right, rychlost, TouchZavora, HowFarUntilFrontRow, HowFarUntilBackRow, US
  Drive_Forward_Until_Block_Detected()
  while motor_retry(left, left.current_angle) <= HowFarUntilBackRow or motor_retry(right, right.current_angle) <= HowFarUntilBackRow:
    print(sensor_retry(gyro, gyro.angle))
    motor_retry(left, lambda: left.run_at_speed(180 - 8 * sensor_retry(gyro, gyro.angle)))
    motor_retry(right, lambda: right.run_at_speed(180 + 8 * sensor_retry(gyro, gyro.angle)))
  motor_retry(left, left.brake)
  motor_retry(right, right.brake)

# Popište tuto funkci...
def Gate_collect_block():
  global HowFar_, gyro, pas, left, Start_stop, right, rychlost, TouchZavora, HowFarUntilFrontRow, HowFarUntilBackRow, US
  motor_retry(pas, lambda: pas.reset_angle(0))
  print('zacatek zavory')
  while not sensor_retry(TouchZavora, TouchZavora.is_pressed):
    motor_retry(pas, lambda: pas.run_at_speed(-720))
  print('narazil jsem')
  motor_retry(pas, pas.brake)
  print('zavrel jsem')
  motor_retry(pas, lambda: pas.rotate_by_angle(0 - motor_retry(pas, pas.current_angle), 720))

# Popište tuto funkci...
def Gate_close():
  global HowFar_, gyro, pas, left, Start_stop, right, rychlost, TouchZavora, HowFarUntilFrontRow, HowFarUntilBackRow, US
  motor_retry(pas, lambda: pas.reset_angle(0))
  print('zacatek zavory')
  while not sensor_retry(TouchZavora, TouchZavora.is_pressed):
    motor_retry(pas, lambda: pas.run_at_speed(-720))
  print('narazil jsem')
  motor_retry(pas, pas.brake)
  motor_retry(pas, pas.hold)

# Popište tuto funkci...
def Gate_open():
  global HowFar_, gyro, pas, left, Start_stop, right, rychlost, TouchZavora, HowFarUntilFrontRow, HowFarUntilBackRow, US
  motor_retry(pas, lambda: pas.rotate_by_angle(0 - motor_retry(pas, pas.current_angle), -720))

# Popište tuto funkci...
def Turn_left():
  global HowFar_, gyro, pas, left, Start_stop, right, rychlost, TouchZavora, HowFarUntilFrontRow, HowFarUntilBackRow, US
  time.sleep(0.5)
  sensor_retry(gyro, gyro.set_zero_point)
  while not sensor_retry(gyro, gyro.angle) <= -90:
    print(sensor_retry(gyro, gyro.angle))
